import { HorizontalDivider, PuzzleInfoBox } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import img1 from "./assets/1.png";
import img2 from "./assets/2.png";
import img3 from "./assets/3.png";
import img4 from "./assets/4.png";
import img5 from "./assets/5.png";
import img6 from "./assets/6.png";
import img7 from "./assets/7.png";

export type PossibleAnswer = string | null;
export const EMPTY_ANSWERS: PossibleAnswer[] = [null, null, null, null, null];

const LOCATIONS = [
  "Bandit Camp",
  "Battlefield of Khazard",
  "Castle Wars",
  "Chaos Temple",
  "Digsite",
  "Emir's Arena",
  "Feldip Hills",
  "Ferox Enclave",
  "Fortis Colosseum",
  "Fossil Island",
  "Gnome Stronghold",
  "Grand Exchange",
  "Jaleustrophos",
  "Jalsavrah",
  "Prifddinas",
  "Tree Gnome Village",
  "Xeric's Lookout",
];

const NONSENSE1 = [
  "THEBOTTLEYSCRAPER",
  "REPUTATIONROLEAU",
  "MEXTREMEMANSION",
  "SEARUN",
  "IBMIMAGECUP",
  "HOWARDLIVES",
  "DAUGHTEREACH",
  "INNVIRTUALLYBE",
  "EPITHETMEASURE",
  "CLOISTERLIFE",
  "ABSURDTOSHOW",
  "SENTANGEL",
  "TITLECBIZ",
];

const CLUES = [
  "Enormous Munchy Avian Pursuing",
  "Helping a man overcome his fears in his sleep",
  "Man becomes poultry in a spooky mansion",
  "...of a Drunken Dwarf",
  "Famous wizard got stuck in glass mineral",
  "Puzzling homicide in the mansion",
  "Killing a tyrant in a forest full of traps",
  "Zombie pirates are thirsty and angry",
  "Colourful livestock causing the plague",
  "Do I side with the Mahjarrat or Armadyl?",
  "Big sapling poisoned by a hidden stone",
];

const NONSENSE2 = [
  "HUTK EGXJ",
  "UJSTUDSO AKDW",
  "NMVSMVABZIQVA KIABTM",
  "BMVQZTVMY JA NCVYJRN",
  "FDIBNOJRI",
  "IXSX AOXDLK FPIB",
  "UMQGMZLQBKP",
  "AZCE ASLDXLEJD",
  "ZOHFGPH YBPU",
  "ZSLWL",
  "OCZ AJMBJOOZI XZHZOZMT",
  "CPULYF",
];

const DEFAULT_CHEST_TEXT = "Solve more clues to open this casket.";
const DEFAULT_CHEST_ALT = "A casket (that looks like a chest)";
const DEFAULT_CHEST_LINES: string[] = [];

const ANSWERS = ["OBELISK", "GUTHIX", "PICKPOCKETING", "RIGOUR", "SPIDER"];

const PARTIALS: [string, string][][] = [
  [],
  [],
  [["SUMUPRUNECOST", "SUM UP RUNE COST: Keep going!"]],
  [],
  [["THREECROSSES", "THREE CROSSES: Keep going!"]],
];

const CHEST_DESCRIPTIONS = [
  "5 items with numbers to the top-left of them, in a 2-row 3-column grid with the bottom-right missing:",
  "A brown tied bag with the number 3 to the top-left",
  "A piece of paper with five short lines of writing with the number 5 to the top-left",
  "A purple oval with a smaller deeper-purple oval inside and an even deeper-purple many-pointed shape inside with the number 4 to the top-left",
  "A rolled-up green scroll with the number 3 to the top-left",
  "A bunch of blue spheres in a see-through container with the number 1 to the top-left",
];

const normalizeGuess = (value: string): string =>
  value.toUpperCase().replace(/[^A-Z]/g, "");

const normalizeAnswer = (answers: PossibleAnswer[]): PossibleAnswer[] => {
  if (answers.length !== 5) return [...EMPTY_ANSWERS];
  return answers.map((ans) =>
    typeof ans === "string" || ans === null ? ans : null,
  );
};

const ClueArbiterComponent = ({
  getStorage,
  setStorage,
}: {
  getStorage: () => PossibleAnswer[];
  setStorage: (x: PossibleAnswer[]) => void;
}) => {
  const [storedAnswers, setStoredAnswers] = useState<PossibleAnswer[]>(() =>
    normalizeAnswer(getStorage()),
  );
  const [messages, setMessages] = useState<string[]>(() =>
    storedAnswers.map((ans) => ans ?? ""),
  );
  const [inputs, setInputs] = useState<string[]>(["", "", "", "", ""]);
  const [lastSubmissionTime, setLastSubmissionTime] = useState<number[]>([
    0, 0, 0, 0, 0,
  ]);
  const [processingGuess, setProcessingGuess] = useState<boolean[]>([
    false,
    false,
    false,
    false,
    false,
  ]);
  const [chestText, setChestText] = useState(DEFAULT_CHEST_TEXT);
  const [chestSrc, setChestSrc] = useState(img6);
  const [chestAlt, setChestAlt] = useState(DEFAULT_CHEST_ALT);
  const [chestLines, setChestLines] = useState(DEFAULT_CHEST_LINES);

  const onCheckAll = useCallback((answers: PossibleAnswer[]) => {
    const solvedEnough =
      answers.filter(
        (ans, idx) => ans !== null && normalizeGuess(ans) === ANSWERS[idx],
      ).length >= 3;
    if (!solvedEnough) {
      return;
    }
    setChestText("");
    setChestSrc(img7);
    setChestAlt(
      "An open casket (that looks like a chest), with five items, each with a number to the top-left of it. The items are arranged in a 2-row 3-column grid with the bottom-right missing. See copy-to-clipboard text for detailed descriptions.",
    );
    setChestLines(CHEST_DESCRIPTIONS);
  }, []);

  useEffect(() => {
    onCheckAll(storedAnswers);
    // We want to only run this once at the start of the file;
    // otherwise, we manually re-check on correct answer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onCheckAll]);

  const submitAnswer = useCallback(
    (checkerId: number) => {
      if (inputs[checkerId].length === 0) return;

      if (processingGuess[checkerId]) {
        setMessages((prev) => {
          const next = [...prev];
          next[checkerId] = "Still processing previous guess";
          return next;
        });
        return;
      }

      if (Date.now() - lastSubmissionTime[checkerId] < 60000) {
        setMessages((prev) => {
          const next = [...prev];
          next[checkerId] = "Rate-limited (1/minute)";
          return next;
        });
        return;
      }

      setProcessingGuess((prev) => {
        const next = [...prev];
        next[checkerId] = true;
        return next;
      });

      const normalized = normalizeGuess(inputs[checkerId]);
      let result: { answer: PossibleAnswer; text: string } = {
        answer: null,
        text: `${normalized}: Incorrect.`,
      };
      if (normalized === ANSWERS[checkerId]) {
        result = { answer: normalized, text: normalized };
      }
      for (const [alt, message] of PARTIALS[checkerId]) {
        if (normalized === alt) {
          result = { answer: null, text: message };
          break;
        }
      }

      setStoredAnswers((prev) => {
        const next = prev.map((ans, idx) =>
          idx === checkerId ? result.answer : ans,
        );
        setStorage(next);
        if (result.answer !== null) onCheckAll(next);
        return next;
      });

      setMessages((prev) => {
        const next = [...prev];
        next[checkerId] = result.text;
        return next;
      });

      if (result.text.includes("Incorrect")) {
        setLastSubmissionTime((prev) => {
          const next = [...prev];
          next[checkerId] = Date.now();
          return next;
        });
      }

      setProcessingGuess((prev) => {
        const next = [...prev];
        next[checkerId] = false;
        return next;
      });
    },
    [inputs, processingGuess, lastSubmissionTime, setStorage, onCheckAll],
  );

  const onKeyDown = useCallback(
    (i: number): React.KeyboardEventHandler<HTMLInputElement> =>
      (e) => {
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          submitAnswer(i);
        }
      },
    [submitAnswer],
  );

  const checkerRow = useCallback(
    (checkerId: number) => {
      const solved = storedAnswers[checkerId] !== null;
      const text = messages[checkerId];
      return solved ? (
        <span>{text} ✅</span>
      ) : (
        <>
          <input
            value={inputs[checkerId]}
            onChange={(e) => {
              const updated = [...inputs];
              updated[checkerId] = e.target.value;
              setInputs(updated);
            }}
            onKeyDown={onKeyDown(checkerId)}
            className="border border-black"
          />
          <button
            type="button"
            onClick={() => {
              submitAnswer(checkerId);
            }}
            disabled={inputs[checkerId].length === 0}
            className={cn(
              "ml-2 rounded-2xl px-4 py-2 shadow-sm border bg-white hover:bg-gray-50 disabled:opacity-50",
              inputs[checkerId].length === 0 && "cursor-not-allowed",
            )}
          >
            Check
          </button>
          <span className="ml-2">{text}</span>
        </>
      );
    },
    [messages, inputs, storedAnswers, submitAnswer, onKeyDown],
  );
  const checkers = useMemo(
    () => [0, 1, 2, 3, 4].map((idx) => checkerRow(idx)),
    [checkerRow],
  );

  return (
    <>
      <PuzzleInfoBox copyable={false}>
        Which puzzles are solved is stored in your browser, not across the team,
        so make sure someone inputs all the answers your team has. Also,
        descriptions of the images are available via copy-to-clipboard.
      </PuzzleInfoBox>
      <div className={COPY_ONLY_CLASS}>
        Which puzzles are solved is stored in your browser, not across the team,
        so make sure someone inputs all the answers your team has.
      </div>
      <div className={NO_COPY_CLASS}>{checkers[0]}</div>
      <img src={img1} alt="Description in copyable text below" />
      <div className={COPY_ONLY_CLASS}>
        <ul>
          <li>Armaments so special, every monster cowers</li>
          <li>How many times can you use their powers</li>
        </ul>
        <p className="mt-8">2 rows of 5 images</p>
        <p className="mt-4">Row 1 (left-to-right):</p>
        <ul>
          <li>Long bladed weapon with a pointy red blade</li>
          <li>
            Large bladed weapon with a purple cross in a circle ornament at the
            handle
          </li>
          <li>Large bladed weapon with a golden blade</li>
          <li>Bladed weapon with a gray blade and purple gem</li>
          <li>Bladed weapon with a protective guard on the handle</li>
        </ul>
        <p className="mt-4">Row 2 (left-to-right):</p>
        <ul>
          <li>Ranged weapon with a red handle</li>
          <li>
            Two almost-identical blunt weapons next to each other with red and
            purple line etchings
          </li>
          <li>Large shield with a green eye in the center</li>
          <li>Short bladed weapon with a dark red blade</li>
          <li>Bladed weapon with a sun ornament at the handle</li>
        </ul>
      </div>
      <HorizontalDivider />
      <div className={NO_COPY_CLASS}>{checkers[1]}</div>
      <img src={img2} alt="Description in copyable text below" />
      <div className={COPY_ONLY_CLASS}>
        <ul>
          <li>How many places can you go</li>
          <li>With what the images here show</li>
        </ul>
        <ul className="mt-8">
          {LOCATIONS.map((i, ind) => (
            <li key={ind}>{i}</li>
          ))}
        </ul>
        <p className="mt-8">
          A line with 6 pairs of 2 small emoji-like images each:
        </p>
        <ul>
          <li>Ring and Two Crossed Swords</li>
          <li>Fire and Necklace</li>
          <li>Ghost and Tree</li>
          <li>Man With A Crown and Sceptre</li>
          <li>Pickaxe and Necklace</li>
          <li>Wizard and Necklace</li>
        </ul>
      </div>
      <HorizontalDivider />
      <div className={NO_COPY_CLASS}>{checkers[2]}</div>
      <img src={img3} alt="Description in copyable text below" />
      <div className={COPY_ONLY_CLASS}>
        <ul>
          <li>Removing a spare</li>
          <li>Each cast you repair</li>
        </ul>
        <ul className="mt-8">
          {NONSENSE1.map((i, ind) => (
            <li key={ind}>{i}</li>
          ))}
        </ul>
        <p className="mt-8">_ _ _ _ _ _ _ _ _ _ _ _ _</p>
      </div>
      <HorizontalDivider />
      <div className={NO_COPY_CLASS}>{checkers[3]}</div>
      <img src={img4} alt="Description in copyable text below" />
      <div className={COPY_ONLY_CLASS}>
        <ul>
          <li>Sort what the diary has recorded</li>
          <li>Count points the adventures rewarded</li>
        </ul>
        <ul className="mt-8">
          {CLUES.map((i, ind) => (
            <li key={ind}>{i}</li>
          ))}
        </ul>
        <p className="mt-8">_ _ _ _ _ _</p>
      </div>
      <HorizontalDivider />
      <div className={NO_COPY_CLASS}>{checkers[4]}</div>
      <img src={img5} alt="Description in copyable text below" />
      <div className={COPY_ONLY_CLASS}>
        <ul>
          <li>The symbols are shifted</li>
          <li>Locations depicted</li>
        </ul>
        <ul className="mt-8">
          {NONSENSE2.map((i, ind) => (
            <li key={ind}>{i}</li>
          ))}
        </ul>
        <ul className="mt-8">
          <li>The map will show</li>
          <li>What lies below</li>
        </ul>
        <p className="mt-8">_ _ _ _ _ _</p>
      </div>
      <HorizontalDivider />
      <p>{chestText}</p>
      <div aria-live="polite" aria-atomic="true">
        <img src={chestSrc} alt={chestAlt} />
        <span className="sr-only">{chestAlt}</span>
      </div>
      {chestLines.length > 0 && (
        <div className={COPY_ONLY_CLASS}>
          <p>{chestLines[0]}</p>
          <ul>
            {chestLines.slice(1).map((line, i) => (
              <li key={i}>{line}</li>
            ))}
          </ul>
        </div>
      )}
    </>
  );
};

export default ClueArbiterComponent;
