import React from "react";
import { createRoot } from "react-dom/client";
import { z } from "zod";
import ClueArbiterComponent, {
  EMPTY_ANSWERS,
  type PossibleAnswer,
} from "./ClueArbiterComponent";

const elem = document.getElementById("puzzle-content-root");
if (elem) {
  const PossibleAnswerArray = z.array(z.string().nullable());
  const storage = (window as unknown as { localStorage: Storage }).localStorage;
  const getStorage = (): PossibleAnswer[] => {
    const raw = storage.getItem("clue-arbiter-data");
    if (raw === null) return [...EMPTY_ANSWERS];
    const safe = PossibleAnswerArray.safeParse(JSON.parse(raw));
    return safe.success ? safe.data : [...EMPTY_ANSWERS];
  };
  const setStorage = (x: PossibleAnswer[]) => {
    storage.setItem("clue-arbiter-data", JSON.stringify(x));
  };
  const root = createRoot(elem);
  root.render(
    <ClueArbiterComponent getStorage={getStorage} setStorage={setStorage} />,
  );
} else {
  console.error(
    "Could not mount ClueArbiterComponent because #puzzle-content-root was nowhere to be found",
  );
}
